// macOS reads the bold app-name shown in the system menu bar (and the Dock hover tooltip)
// from the actual running app bundle's Info.plist — not from anything Electron's JS layer
// can influence. app.setName() and a custom Menu template's label are both silently ignored
// there; only editing node_modules/electron/dist/Electron.app/Contents/Info.plist directly
// actually changes it. That file is regenerated by every `npm install`, so this has to run
// as a postinstall step to stick — a one-off manual edit reverts on the next install.
import { execFileSync } from 'node:child_process'
import { existsSync } from 'node:fs'
import path from 'node:path'
import { createRequire } from 'node:module'

const APP_NAME = 'AllisonIPTV'

if (process.platform !== 'darwin') {
  process.exit(0)
}

const require = createRequire(import.meta.url)

let electronBinaryPath
try {
  // The "electron" npm package's main export is the path to its binary when required from
  // plain Node (as opposed to from within a running Electron process) — the same mechanism
  // tools like electron-builder use to locate it.
  electronBinaryPath = require('electron')
} catch {
  process.exit(0) // electron not resolvable yet (e.g. very first install pass) — nothing to patch
}

// .../node_modules/electron/dist/Electron.app/Contents/MacOS/Electron -> .../Electron.app
const appBundlePath = path.resolve(electronBinaryPath, '../../..')
const infoPlistPath = path.join(appBundlePath, 'Contents/Info.plist')

if (!existsSync(infoPlistPath)) {
  process.exit(0)
}

try {
  execFileSync('/usr/libexec/PlistBuddy', ['-c', `Set :CFBundleName ${APP_NAME}`, infoPlistPath])
  execFileSync('/usr/libexec/PlistBuddy', ['-c', `Set :CFBundleDisplayName ${APP_NAME}`, infoPlistPath])
  console.log(`[postinstall] Renamed dev Electron.app bundle to "${APP_NAME}" (macOS menu bar/Dock name).`)
} catch (err) {
  // Best-effort and non-fatal — a failed rename here shouldn't break `npm install` for anyone.
  console.warn('[postinstall] Could not rename dev Electron.app bundle:', err instanceof Error ? err.message : err)
}
